import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

function EmployeeDashboard() {
  const navigate = useNavigate();

  const defaultEmployees = [
    { id: 1, name: "Gopal", position: "Manager", mobile: "1234567890" },
    { id: 2, name: "Kumar", position: "Developer", mobile: "0987654321" },
    { id: 3, name: "Ravi", position: "Developer", mobile: "1112223333" },
  ];

  const [employees, setEmployees] = useState(() => {
    const stored = localStorage.getItem("employees");
    if (stored) {
      const parsedEmployees = JSON.parse(stored);
      return parsedEmployees.length === 0 ? defaultEmployees : parsedEmployees;
    }
    return defaultEmployees;
  });

  // Independent sort directions per column
  const [sortDirections, setSortDirections] = useState({
    name: "asc",
    position: "asc",
  });
  // Active sort column key
  const [activeSortKey, setActiveSortKey] = useState("name");

  const [showAddForm, setShowAddForm] = useState(false);
  const [newEmployeeName, setNewEmployeeName] = useState("");
  const [newEmployeePosition, setNewEmployeePosition] = useState("");
  const [newEmployeeMobile, setNewEmployeeMobile] = useState("");
  const [searchText, setSearchText] = useState("");
  const [editEmployeeId, setEditEmployeeId] = useState(null);
  const [editEmployeeName, setEditEmployeeName] = useState("");
  const [editEmployeePosition, setEditEmployeePosition] = useState("");
  const [editEmployeeMobile, setEditEmployeeMobile] = useState("");

  const positions = ["Manager", "Developer", "Designer", "QA", "HR"];

  useEffect(() => {
    localStorage.setItem("employees", JSON.stringify(employees));
  }, [employees]);

  const handleAddEmployeeClick = () => {
    setShowAddForm(true);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (
      !newEmployeeName.trim() ||
      !newEmployeePosition.trim() ||
      !newEmployeeMobile.trim()
    ) {
      alert("All Fields Are Required.");
      return;
    }
    const newEmployee = {
      id: employees.length ? Math.max(...employees.map((e) => e.id)) + 1 : 1,
      name: newEmployeeName.trim(),
      position: newEmployeePosition.trim(),
      mobile: newEmployeeMobile.trim(),
    };
    setEmployees([...employees, newEmployee]);
    setNewEmployeeName("");
    setNewEmployeePosition("");
    setNewEmployeeMobile("");
    setShowAddForm(false);
  };

  const handleEditClick = (employee) => {
    setEditEmployeeId(employee.id);
    setEditEmployeeName(employee.name);
    setEditEmployeePosition(employee.position);
    setEditEmployeeMobile(employee.mobile || "");
  };

  const handleEditSave = () => {
    if (
      !editEmployeeName.trim() ||
      !editEmployeePosition.trim() ||
      !editEmployeeMobile.trim()
    ) {
      alert("Please enter all fields.");
      return;
    }
    setEmployees(
      employees.map((emp) =>
        emp.id === editEmployeeId
          ? {
              ...emp,
              name: editEmployeeName.trim(),
              position: editEmployeePosition.trim(),
              mobile: editEmployeeMobile.trim(),
            }
          : emp
      )
    );
    setEditEmployeeId(null);
    setEditEmployeeName("");
    setEditEmployeePosition("");
    setEditEmployeeMobile("");
  };

  const handleEditCancel = () => {
    setEditEmployeeId(null);
    setEditEmployeeName("");
    setEditEmployeePosition("");
    setEditEmployeeMobile("");
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this employee?")) {
      setEmployees(employees.filter((emp) => emp.id !== id));
    }
  };

  const filteredEmployees = employees.filter(
    (emp) =>
      emp.name.toLowerCase().includes(searchText.toLowerCase()) ||
      emp.position.toLowerCase().includes(searchText.toLowerCase()) ||
      emp.mobile.includes(searchText)
  );

  // Sorted employees by activeSortKey and its direction
  const sortedEmployees = React.useMemo(() => {
    let sortableEmployees = [...filteredEmployees];
    if (activeSortKey) {
      const direction = sortDirections[activeSortKey];
      sortableEmployees.sort((a, b) => {
        const aKey = a[activeSortKey].toLowerCase();
        const bKey = b[activeSortKey].toLowerCase();
        if (aKey < bKey) return direction === "asc" ? -1 : 1;
        if (aKey > bKey) return direction === "asc" ? 1 : -1;
        return 0;
      });
    }
    return sortableEmployees;
  }, [filteredEmployees, activeSortKey, sortDirections]);

  const handleHeaderClick = (key) => {
    setActiveSortKey(key);
    setSortDirections((prev) => ({
      ...prev,
      [key]: prev[key] === "asc" ? "desc" : "asc",
    }));
  };

  const getSortArrowName = () => (sortDirections.name === "asc" ? " ▲" : " ▼");
  const getSortArrowPosition = () =>
    sortDirections.position === "asc" ? " ▲" : " ▼";

  return (
    <div style={{ padding: 20 }}>
      <button
        onClick={() => navigate(-1)}
        style={styles.goBackButton}
        onMouseOver={(e) => (e.currentTarget.style.backgroundColor = "#0056b3")}
        onMouseOut={(e) => (e.currentTarget.style.backgroundColor = "#007bff")}
      >
        Go Back
      </button>

      {/* Wrapper for Add and Search */}
      <div
        style={{
          marginTop: 20,
          marginBottom: 20,
          display: "flex",
          alignItems: "center",
          justifyContent: "flex-end",
        }}
      >
        <button onClick={handleAddEmployeeClick} style={styles.addButton}>
          Add Employee
        </button>

        <input
          type="text"
          placeholder="Search employees / Position"
          value={searchText}
          onChange={(e) => setSearchText(e.target.value)}
          style={{
            marginLeft: 20,
            padding: 8,
            fontSize: 16,
            borderRadius: 6,
            border: "1px solid #ccc",
            width: 200,
          }}
        />
      </div>

      {/* Add Employee Form */}
      {showAddForm && (
        <div style={styles.formContainer}>
          <form onSubmit={handleSubmit} style={{ display: "flex", gap: 10 }}>
            <input
              type="text"
              placeholder="Employee Name"
              value={newEmployeeName}
              onChange={(e) => setNewEmployeeName(e.target.value)}
              style={styles.inputField}
              required
            />
            <select
              value={newEmployeePosition}
              onChange={(e) => setNewEmployeePosition(e.target.value)}
              style={{ ...styles.inputField, backgroundColor: "white" }}
              required
            >
              <option value="" disabled>
                Select Position
              </option>
              {positions.map((pos) => (
                <option key={pos} value={pos}>
                  {pos}
                </option>
              ))}
            </select>
            <input
              type="text"
              placeholder="Mobile Number"
              value={newEmployeeMobile}
              onChange={(e) => {
                const val = e.target.value;
                if (/^\d{0,10}$/.test(val)) {
                  setNewEmployeeMobile(val);
                }
              }}
              style={styles.inputField}
              required
              maxLength={10}
            />
            <button type="submit" style={styles.submitButton}>
              Add
            </button>
            <button
              type="button"
              onClick={() => setShowAddForm(false)}
              style={styles.cancelButton}
            >
              Cancel
            </button>
          </form>
        </div>
      )}
      {/* Employee Table */}
      <div style={styles.tableContainer}>
        {sortedEmployees.length === 0 ? (
          <p>No employees found.</p>
        ) : (
          <table style={styles.table}>
            <thead>
              <tr>
                <th
                  style={styles.tableHeader}
                  onClick={() => handleHeaderClick("name")}
                >
                  Name{getSortArrowName()}
                </th>
                <th
                  style={styles.tableHeader}
                  onClick={() => handleHeaderClick("position")}
                >
                  Position{getSortArrowPosition()}
                </th>
                <th style={styles.tableHeader}>Mobile</th>
                <th style={styles.tableHeader}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {sortedEmployees.map((emp) => (
                <tr key={emp.id} style={styles.tableRow}>
                  <td style={styles.tableCell}>
                    {editEmployeeId === emp.id ? (
                      <input
                        type="text"
                        value={editEmployeeName}
                        onChange={(e) => setEditEmployeeName(e.target.value)}
                        style={styles.inputField}
                      />
                    ) : (
                      emp.name
                    )}
                  </td>
                  <td style={styles.tableCell}>
                    {editEmployeeId === emp.id ? (
                      <select
                        value={editEmployeePosition}
                        onChange={(e) =>
                          setEditEmployeePosition(e.target.value)
                        }
                        style={{
                          ...styles.inputField,
                          backgroundColor: "white",
                        }}
                        required
                      >
                        <option value="" disabled>
                          Select Position
                        </option>
                        {positions.map((pos) => (
                          <option key={pos} value={pos}>
                            {pos}
                          </option>
                        ))}
                      </select>
                    ) : (
                      emp.position
                    )}
                  </td>
                  <td style={styles.tableCell}>
                    {editEmployeeId === emp.id ? (
                      <input
                        type="text"
                        value={editEmployeeMobile}
                        onChange={(e) => setEditEmployeeMobile(e.target.value)}
                        style={styles.inputField}
                      />
                    ) : (
                      emp.mobile
                    )}
                  </td>
                  <td style={styles.tableCell}>
                    {editEmployeeId === emp.id ? (
                      <>
                        <button
                          onClick={handleEditSave}
                          style={styles.actionButton}
                        >
                          Save
                        </button>
                        <button
                          onClick={handleEditCancel}
                          style={{
                            ...styles.actionButton,
                            marginLeft: 8,
                            backgroundColor: "#6c757d",
                          }}
                        >
                          Cancel
                        </button>
                      </>
                    ) : (
                      <>
                        <button
                          onClick={() => handleEditClick(emp)}
                          style={styles.actionButton}
                        >
                          Edit
                        </button>
                        <button
                          onClick={() => handleDelete(emp.id)}
                          style={{
                            ...styles.actionButton,
                            marginLeft: 8,
                            backgroundColor: "#dc3545",
                          }}
                        >
                          Delete
                        </button>
                      </>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

const styles = {
  goBackButton: {
    padding: "10px 20px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: 6,
    cursor: "pointer",
    fontSize: 16,
  },
  addButton: {
    marginLeft: 20,
    padding: "10px 20px",
    backgroundColor: "#28a745",
    color: "white",
    border: "none",
    borderRadius: 6,
    cursor: "pointer",
    fontSize: 16,
  },
  formContainer: {
    display: "flex",
    justifyContent: "center",
    marginBottom: 20,
  },
  inputField: {
    padding: 8,
    fontSize: 16,
    borderRadius: 6,
    border: "1px solid #ccc",
    width: 200,
  },
  submitButton: {
    marginLeft: 10,
    padding: "8px 16px",
    backgroundColor: "#007bff",
    border: "none",
    borderRadius: 6,
    color: "white",
    cursor: "pointer",
    fontSize: 16,
  },
  cancelButton: {
    marginLeft: 10,
    padding: "8px 16px",
    backgroundColor: "#6c757d",
    border: "none",
    borderRadius: 6,
    color: "white",
    cursor: "pointer",
    fontSize: 16,
  },
  tableContainer: {
    display: "flex",
    justifyContent: "center",
  },
  table: {
    width: "70%",
    borderCollapse: "separate",
    borderSpacing: 0,
    backgroundColor: "#f8f9fa",
    borderRadius: 10,
    overflow: "hidden",
    boxShadow: "6px 15px 20px rgba(0, 0, 0, 0.15)",
  },
  tableHeader: {
    borderBottom: "1px solid #ddd",
    padding: 8,
    textAlign: "center",
    fontWeight: "bold",
    backgroundColor: "#343a40",
    color: "white",
    cursor: "pointer",
    userSelect: "none",
  },
  tableRow: {
    textAlign: "center",
    backgroundColor: "#d0f3c5ff",
    transition: "background-color 0.2s",
  },
  tableCell: {
    fontWeight: "600",
    borderBottom: "1px solid #a8d5a2",
    padding: 8,
    color: "#2e4d24",
  },
  actionButton: {
    padding: "6px 12px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: 4,
    cursor: "pointer",
    fontSize: 14,
  },
};

export default EmployeeDashboard;
